import os
import hmac
import hashlib
import time
import re
import secrets
from urllib.parse import unquote, quote
from pathlib import PurePosixPath

SECRET_KEY = secrets.token_bytes(32)
BASE_DIR = '/var/app/static/public'
MAX_PATH_LEN = 255
ALLOWED_EXTENSIONS = {'.txt', '.html', '.css', '.js', '.png', '.jpg', '.json'}

# Rate limiting state
request_counts = {}
RATE_LIMIT = 100
RATE_WINDOW = 60

def generate_access_token(username, resource_path):
    """Generate HMAC-based access token for resource"""
    timestamp = str(int(time.time()))
    message = f"{username}:{resource_path}:{timestamp}".encode()
    signature = hmac.new(SECRET_KEY, message, hashlib.sha256).hexdigest()
    return f"{timestamp}.{signature}"

def verify_access_token(username, resource_path, token, max_age=3600):
    """Verify HMAC token with expiration"""
    try:
        parts = token.split('.')
        if len(parts) != 2:
            return False
        timestamp_str, provided_sig = parts
        timestamp = int(timestamp_str)
        if time.time() - timestamp > max_age:
            return False
        message = f"{username}:{resource_path}:{timestamp_str}".encode()
        expected_sig = hmac.new(SECRET_KEY, message, hashlib.sha256).hexdigest()
        return hmac.compare_digest(provided_sig, expected_sig)
    except (ValueError, TypeError):
        return False

def check_rate_limit(client_ip):
    """Sliding window rate limiter"""
    now = time.time()
    if client_ip not in request_counts:
        request_counts[client_ip] = []
    # Clean old entries
    request_counts[client_ip] = [
        t for t in request_counts[client_ip] if now - t < RATE_WINDOW
    ]
    if len(request_counts[client_ip]) >= RATE_LIMIT:
        return False
    request_counts[client_ip].append(now)
    return True

def validate_extension(filepath):
    """Check file extension against allowlist"""
    _, ext = os.path.splitext(filepath)
    return ext.lower() in ALLOWED_EXTENSIONS

def sanitize_path_component(component):
    """Remove dangerous characters from a single path component."""
    # Strip null bytes
    cleaned = component.replace('\x00', '')
    # Reject components that are path traversal
    if cleaned in ('.', '..') or '/' in cleaned or '\\' in cleaned:
        return None
    # Only allow safe characters
    if not re.match(r'^[a-zA-Z0-9._\-]+$', cleaned):
        return None
    return cleaned

def resolve_safe_path(user_path):
    """Resolve user-supplied path safely within BASE_DIR.

    Security: Validates each component individually,
    then joins with BASE_DIR and verifies containment.
    """
    if not user_path or len(user_path) > MAX_PATH_LEN:
        return None

    # Reject any URL-encoded characters - require clean input
    if '%' in user_path:
        return None

    # Reject obvious traversal patterns
    if '..' in user_path:
        return None

    # Split into components and validate each
    components = user_path.strip('/').split('/')
    safe_components = []
    for comp in components:
        if not comp:
            continue
        sanitized = sanitize_path_component(comp)
        if sanitized is None:
            return None
        safe_components.append(sanitized)

    if not safe_components:
        return None

    # Join with base directory
    target = os.path.join(BASE_DIR, *safe_components)

    # Normalize to resolve any remaining relative components
    target = os.path.normpath(target)

    # Final containment check - use normpath on both sides
    base_normalized = os.path.normpath(BASE_DIR)
    if not target.startswith(base_normalized + os.sep):
        if target != base_normalized:
            return None

    return target

def serve_file(request):
    """Main file serving endpoint with full security checks.

    Request format: {
        'client_ip': str,
        'username': str,
        'path': str,       # Clean path to resource (no URL encoding)
        'token': str       # HMAC access token
    }
    """
    client_ip = request.get('client_ip', '')
    username = request.get('username', '')
    raw_path = request.get('path', '')
    token = request.get('token', '')

    # Rate limiting
    if not check_rate_limit(client_ip):
        return {'status': 429, 'body': 'Rate limit exceeded'}

    # Input validation
    if not username or not raw_path or not token:
        return {'status': 400, 'body': 'Missing required fields'}

    if not re.match(r'^[a-zA-Z0-9_]{1,64}$', username):
        return {'status': 400, 'body': 'Invalid username format'}

    # Verify access token
    if not verify_access_token(username, raw_path, token):
        return {'status': 403, 'body': 'Invalid or expired token'}

    # Resolve and validate path
    safe_path = resolve_safe_path(raw_path)
    if safe_path is None:
        return {'status': 400, 'body': 'Invalid path'}

    # Validate extension
    if not validate_extension(safe_path):
        return {'status': 403, 'body': 'File type not allowed'}

    # Check file exists and is a regular file
    if not os.path.isfile(safe_path):
        return {'status': 404, 'body': 'File not found'}

    # Serve the file
    try:
        with open(safe_path, 'r') as f:
            content = f.read()
        return {'status': 200, 'body': content}
    except (IOError, PermissionError):
        return {'status': 500, 'body': 'Internal error'}
